public static int computeWithHeap(int[] nums, int k) {
    PriorityQueue<Integer> minHeap = new PriorityQueue<>();

    for (int num : nums) {
        minHeap.offer(num);
        if (minHeap.size() > k) {
            minHeap.poll();
        }
    }

    return minHeap.peek();
}

public static int computeWithMaxHeap(int[] nums, int k) {
    PriorityQueue<Integer> maxHeap = new PriorityQueue<>((a, b) -> b - a);
    for (int num : nums) {
        maxHeap.offer(num);
    }

    for (int i = 0; i < k - 1; i++) {
        maxHeap.poll();
    }

    return maxHeap.peek();
}

public static int computeWithQuickSelect(int[] nums, int k) {
    int left = 0;
    int right = nums.length - 1;
    int targetIndex = nums.length - k;

    while (left <= right) {
        int pivotIndex = partition(nums, left, right);
        if (pivotIndex == targetIndex) {
            return nums[pivotIndex];
        } else if (pivotIndex < targetIndex) {
            left = pivotIndex + 1;
        } else {
            right = pivotIndex - 1;
        }
    }

    return -1;
}

public static int computeWithSorting(int[] nums, int k) {
    java.util.Arrays.sort(nums);
    return nums[nums.length - k];
}
